const o=[{id:"software-engineer",title:"Software Engineer",location:"New York",department:"Deployment",employmentType:"Full time",summary:"Sit with investment firms, turn ambiguous AI goals into production systems, and own the path from first conversation to live deployment.",sections:[{heading:"About Rengo AI",blocks:[{type:"paragraph",text:"Rengo AI is the AI deployment company for investment firms. Embedded alongside investment, finance, and operations teams, we turn fragmented knowledge into shared data infrastructure and deploy purpose-built agents and applications on top of it."},{type:"paragraph",text:"Rengo gives teams access to their firm's collective intelligence, transforming institutional memory into an asset that compounds with every workflow, investment, and decision."}]},{heading:"The Role",blocks:[{type:"paragraph",text:"AI is fundamentally changing how engineering is performed. Engineers used to live on the factory line building the product. The job is now to be the one building the factory. This role is for people who are comfortable owning end-to-end technical outcomes but specifically can continue being impactful when given an ambiguous problem."},{type:"paragraph",text:"You'll work on a small, high-caliber team building AI products for our clients. You'll set technical direction, write code, and be the person the team looks to when something is hard."}]},{heading:"What You Bring",blocks:[{type:"list",items:["Engineering experience, with deep care for the craft. You've shipped multiple complete products end-to-end and write elegant, production-ready code across multiple disciplines.","Specific interest in applying software engineering fundamentals to AI systems. You care about balancing frontier model capabilities with good system design.",'Extreme ownership mindset. You jump in without instruction, embrace a "no job too big, no job too small" mindset, and want to shape strategy and culture.']}]},{heading:"Benefits",blocks:[{type:"list",items:["Competitive Compensation Package: Attractive salary aligned with your experience and skills.","Unlimited PTO: Take the time you need to relax and rejuvenate.","Exceptional Medical, Dental, and Vision Coverage: Comprehensive health benefits to keep you and your family healthy.","Commuter Benefits: Make your travel to work easier and more affordable.","Life Insurance: Providing peace of mind for you and your loved ones."]}]},{heading:"How Rengo AI is different",blocks:[{type:"paragraph",text:"A typical engineer here owns a product surface area that would normally be covered by an entire team. You'll have outsized autonomy over the products and features you build, and you'll be working at the frontier of what it means to design a product entirely around AI."},{type:"paragraph",text:"This is one of the most transformative moments in the history of technology. We're leaning into it fully. If you join us, you will too."}]}]}],n=e=>o.find(t=>t.id===e),i=e=>`mailto:careers@rengoai.com?subject=${encodeURIComponent(`Application: ${e}`)}`;export{o as O,n as g,i as r};
